select * from (select job_title, case when salary >= 163000 then 'high' when salary >= 60000 then 'mid' else 'low' end as salary_bucket, avg(salary) as avg_salary from employees where month(hire_date) in (3, 6, 11) group by job_title, case when salary >= 163000 then 'high' when salary >= 60000 then 'mid' else 'low' end) as s where avg_salary >= 60000 order by salary_bucket, avg_salary, job_title limit 10;
